INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0004-000000000001', 'b0000001-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 1, 'verbos-regulares-en-pasado', '{"es": "Verbos Regulares en Pasado", "en": "Regular Verbs in the Past"}'::jsonb, '{"es": "Aprende a formar el pasado simple de los verbos regulares añadiendo -ed, incluyendo las reglas de ortografía y pronunciación.", "en": "Learn to form the simple past of regular verbs by adding -ed, including spelling and pronunciation rules."}'::jsonb, 'grammar', 20, 12, '{"intro": "El pasado simple de los verbos regulares se forma añadiendo -ed al verbo base. En esta lección aprenderás las reglas de ortografía para añadir -ed correctamente, y practicarás solo la forma afirmativa.", "sections": [{"type": "table", "title": "REGLAS DE ORTOGRAFÍA -ED", "headers": ["Regla", "Ejemplo"], "rows": [["La mayoría de los verbos: añade -ed", "walk -> walked / play -> played"], ["Verbos terminados en -e: añade solo -d", "live -> lived / like -> liked"], ["Consonante + y: cambia la y por i y añade -ed", "study -> studied / cry -> cried"], ["Verbo corto consonante-vocal-consonante: dobla la última consonante + ed", "stop -> stopped / plan -> planned"]]}, {"type": "explanation", "title": "PRONUNCIACIÓN DE -ED", "text": "La terminación -ed no siempre suena igual. Se pronuncia /t/ después de sonidos sordos (watched), /d/ después de sonidos sonoros (played), y /ɪd/ después de los sonidos t o d, añadiendo una sílaba extra (wanted, needed)."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I worked yesterday.", "es": "Yo trabajé ayer."}, {"en": "She lived in Madrid.", "es": "Ella vivió en Madrid."}, {"en": "They studied English last year.", "es": "Ellos estudiaron inglés el año pasado."}, {"en": "We stopped at the traffic light.", "es": "Nosotros paramos en el semáforo."}]}, {"type": "note", "variant": "tip", "text": "No necesitas memorizar la pronunciación exacta ahora mismo; con la práctica la irás reconociendo. Concéntrate primero en escribir bien la forma -ed."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0004-0001-000000000001', 'b0000002-0000-0000-0004-000000000001', 1, 'multiple_choice', '{"text": "Choose the correct past form of ''walk'':"}'::jsonb, '{"text": "walked"}'::jsonb, '["walkeded", "walkd", "walking"]'::jsonb, '{"es": "La mayoría de los verbos regulares solo añaden -ed: walk -> walked."}'::jsonb, '{"grammar:past_simple_regular"}'),
('b0000003-0001-0004-0002-000000000001', 'b0000002-0000-0000-0004-000000000001', 2, 'multiple_choice', '{"text": "Choose the correct past form of ''study'':"}'::jsonb, '{"text": "studied"}'::jsonb, '["studyed", "studies", "studing"]'::jsonb, '{"es": "Los verbos terminados en consonante + y cambian la y por i y añaden -ed: study -> studied."}'::jsonb, '{"grammar:past_simple_spelling"}'),
('b0000003-0001-0004-0003-000000000001', 'b0000002-0000-0000-0004-000000000001', 3, 'fill_blank', '{"text": "Yesterday, we ___ (stop) at the traffic light."}'::jsonb, '{"text": "stopped", "accepted": ["stopped"]}'::jsonb, NULL, '{"es": "Stop es un verbo corto consonante-vocal-consonante, por eso se dobla la p: stopped."}'::jsonb, '{"grammar:past_simple_spelling"}'),
('b0000003-0001-0004-0004-000000000001', 'b0000002-0000-0000-0004-000000000001', 4, 'fill_blank', '{"text": "She ___ (live) in Paris for two years."}'::jsonb, '{"text": "lived", "accepted": ["lived"]}'::jsonb, NULL, '{"es": "Live termina en -e, por eso solo se añade -d: lived."}'::jsonb, '{"grammar:past_simple_spelling"}'),
('b0000003-0001-0004-0005-000000000001', 'b0000002-0000-0000-0004-000000000001', 5, 'fill_blank', '{"text": "The baby ___ (cry) all night."}'::jsonb, '{"text": "cried", "accepted": ["cried"]}'::jsonb, NULL, '{"es": "Cry termina en consonante + y, por eso cambia a cried."}'::jsonb, '{"grammar:past_simple_spelling"}'),
('b0000003-0001-0004-0006-000000000001', 'b0000002-0000-0000-0004-000000000001', 6, 'translation', '{"text": "Yo trabajé en una oficina el año pasado."}'::jsonb, '{"text": "I worked in an office last year.", "accepted": ["I worked in an office last year."]}'::jsonb, NULL, NULL, '{"grammar:past_simple_regular"}'),
('b0000003-0001-0004-0007-000000000001', 'b0000002-0000-0000-0004-000000000001', 7, 'translation', '{"text": "Ellos jugaron fútbol el sábado."}'::jsonb, '{"text": "They played football on Saturday.", "accepted": ["They played football on Saturday."]}'::jsonb, NULL, NULL, '{"grammar:past_simple_regular"}'),
('b0000003-0001-0004-0008-000000000001', 'b0000002-0000-0000-0004-000000000001', 8, 'multiple_choice', '{"text": "Which verb has an extra syllable when pronounced in the past tense?"}'::jsonb, '{"text": "wanted"}'::jsonb, '["played", "watched", "worked"]'::jsonb, '{"es": "Wanted se pronuncia con el sonido /ɪd/ porque want termina en t, lo que añade una sílaba extra."}'::jsonb, '{"grammar:past_simple_pronunciation"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0004-000000000002', 'b0000001-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 2, 'negativo-interrogativo-con-did', '{"es": "Pasado Simple: Negativo e Interrogativo con Did", "en": "Past Simple: Negative and Interrogative with Did"}'::jsonb, '{"es": "Aprende a formar negativas y preguntas en pasado simple usando did, el mecanismo universal para todos los verbos.", "en": "Learn to form negatives and questions in the simple past using did, the universal mechanism for all verbs."}'::jsonb, 'grammar', 22, 13, '{"intro": "Para formar el negativo y el interrogativo en pasado simple se usa el auxiliar did con TODOS los verbos, sean regulares o irregulares. Este es el mecanismo más importante del pasado simple en inglés.", "sections": [{"type": "table", "title": "AFIRMATIVO, NEGATIVO E INTERROGATIVO", "headers": ["Forma", "Estructura", "Ejemplo"], "rows": [["Afirmativo", "sujeto + verbo-ed", "I worked yesterday."], ["Negativo", "sujeto + didn''t + verbo base", "I didn''t work yesterday."], ["Interrogativo", "Did + sujeto + verbo base + ?", "Did you work yesterday?"], ["Respuesta corta", "Yes, sujeto + did. / No, sujeto + didn''t.", "Yes, I did. / No, I didn''t."]]}, {"type": "explanation", "title": "REGLA CLAVE", "text": "En el negativo y en las preguntas, el verbo principal SIEMPRE vuelve a su forma base, sin -ed. Esta regla aplica para todos los verbos, regulares e irregulares: didn''t work (no didn''t worked), Did you go...? (no Did you went...?)."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I didn''t watch TV last night.", "es": "Yo no vi televisión anoche."}, {"en": "Did she call you yesterday?", "es": "¿Te llamó ella ayer?"}, {"en": "Yes, she did. / No, she didn''t.", "es": "Sí, lo hizo. / No, no lo hizo."}]}, {"type": "note", "variant": "warning", "text": "Error muy común: ''I didn''t worked'' es INCORRECTO. Como didn''t ya marca el pasado, el verbo debe quedar en forma base: ''I didn''t work''."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0004-0001-000000000001', 'b0000002-0000-0000-0004-000000000002', 1, 'multiple_choice', '{"text": "Choose the correct negative form: She ___ the movie last night."}'::jsonb, '{"text": "didn''t watch"}'::jsonb, '["didn''t watched", "doesn''t watch", "not watched"]'::jsonb, '{"es": "Después de didn''t el verbo vuelve a su forma base: didn''t watch, no didn''t watched."}'::jsonb, '{"grammar:past_simple_negative"}'),
('b0000003-0002-0004-0002-000000000001', 'b0000002-0000-0000-0004-000000000002', 2, 'fill_blank', '{"text": "We ___ (not / study) for the exam."}'::jsonb, '{"text": "didn''t study", "accepted": ["didn''t study", "did not study"]}'::jsonb, NULL, '{"es": "La negación se forma con didn''t + verbo base: didn''t study."}'::jsonb, '{"grammar:past_simple_negative"}'),
('b0000003-0002-0004-0003-000000000001', 'b0000002-0000-0000-0004-000000000002', 3, 'fill_blank', '{"text": "___ you call your mother yesterday?"}'::jsonb, '{"text": "Did", "accepted": ["Did"]}'::jsonb, NULL, '{"es": "Las preguntas en pasado simple empiezan con Did + sujeto + verbo base."}'::jsonb, '{"grammar:did_questions"}'),
('b0000003-0002-0004-0004-000000000001', 'b0000002-0000-0000-0004-000000000002', 4, 'multiple_choice', '{"text": "Choose the correct question: ___ he work on Saturday?"}'::jsonb, '{"text": "Did"}'::jsonb, '["Does", "Was", "Is"]'::jsonb, '{"es": "Para preguntar en pasado simple se usa Did al inicio, sin importar el sujeto."}'::jsonb, '{"grammar:did_questions"}'),
('b0000003-0002-0004-0005-000000000001', 'b0000002-0000-0000-0004-000000000002', 5, 'translation', '{"text": "Yo no trabajé el domingo."}'::jsonb, '{"text": "I didn''t work on Sunday.", "accepted": ["I didn''t work on Sunday.", "I did not work on Sunday."]}'::jsonb, NULL, NULL, '{"grammar:past_simple_negative"}'),
('b0000003-0002-0004-0006-000000000001', 'b0000002-0000-0000-0004-000000000002', 6, 'translation', '{"text": "¿Jugaste fútbol ayer?"}'::jsonb, '{"text": "Did you play football yesterday?", "accepted": ["Did you play football yesterday?"]}'::jsonb, NULL, NULL, '{"grammar:did_questions"}'),
('b0000003-0002-0004-0007-000000000001', 'b0000002-0000-0000-0004-000000000002', 7, 'error_correction', '{"text": "I didn''t worked yesterday.", "error_word": "worked"}'::jsonb, '{"text": "work"}'::jsonb, '["works", "working"]'::jsonb, '{"es": "Después de didn''t el verbo debe estar en forma base: didn''t work, no didn''t worked."}'::jsonb, '{"grammar:past_simple_negative","grammar:did_questions"}'),
('b0000003-0002-0004-0008-000000000001', 'b0000002-0000-0000-0004-000000000002', 8, 'fill_blank', '{"text": "Did you finish the homework? No, I ___."}'::jsonb, '{"text": "didn''t", "accepted": ["didn''t", "did not"]}'::jsonb, NULL, '{"es": "La respuesta corta negativa es No, + sujeto + didn''t."}'::jsonb, '{"grammar:did_questions"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0004-000000000003', 'b0000001-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 3, 'marcadores-de-tiempo-en-pasado', '{"es": "Marcadores de Tiempo en Pasado", "en": "Past Time Expressions"}'::jsonb, '{"es": "Aprende las expresiones de tiempo más comunes para hablar del pasado: yesterday, last night, ago, in + año, y más.", "en": "Learn the most common time expressions for talking about the past: yesterday, last night, ago, in + year, and more."}'::jsonb, 'grammar', 21, 13, '{"intro": "Los marcadores de tiempo indican cuándo ocurrió una acción en el pasado y casi siempre acompañan al pasado simple. Aprenderás las expresiones más comunes y dónde colocarlas en la oración.", "sections": [{"type": "table", "title": "EXPRESIONES DE TIEMPO EN PASADO", "headers": ["Expresión", "Ejemplo"], "rows": [["yesterday", "I called her yesterday."], ["last night / week / month / year", "We watched a movie last night."], ["two days / weeks ago", "She arrived two days ago."], ["in + año", "They lived there in 2010."], ["this morning", "I studied this morning."]]}, {"type": "explanation", "title": "POSICIÓN EN LA ORACIÓN", "text": "Normalmente las expresiones de tiempo van al final de la oración: ''I worked yesterday.'' ''We played tennis last week.'' A veces se colocan al inicio para dar énfasis: ''Last week, we played tennis.''"}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I visited my grandmother last week.", "es": "Visité a mi abuela la semana pasada."}, {"en": "She arrived two weeks ago.", "es": "Ella llegó hace dos semanas."}, {"en": "In 2015, we moved to a new city.", "es": "En 2015, nos mudamos a una nueva ciudad."}]}, {"type": "note", "variant": "tip", "text": "Ago siempre va DESPUÉS de un período de tiempo: two days ago, three years ago. Nunca se coloca antes del número."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0004-0001-000000000001', 'b0000002-0000-0000-0004-000000000003', 1, 'multiple_choice', '{"text": "Choose the correct sentence:"}'::jsonb, '{"text": "We played tennis last Sunday."}'::jsonb, '["We played tennis Sunday last.", "We played tennis last in Sunday.", "We played tennis in last Sunday."]'::jsonb, '{"es": "La expresión de tiempo last Sunday va normalmente al final de la oración, sin preposición adicional."}'::jsonb, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0002-000000000001', 'b0000002-0000-0000-0004-000000000003', 2, 'fill_blank', '{"text": "She called me three days ___."}'::jsonb, '{"text": "ago", "accepted": ["ago"]}'::jsonb, NULL, '{"es": "Ago se coloca después del período de tiempo: three days ago."}'::jsonb, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0003-000000000001', 'b0000002-0000-0000-0004-000000000003', 3, 'fill_blank', '{"text": "They studied English ___ morning."}'::jsonb, '{"text": "this", "accepted": ["this"]}'::jsonb, NULL, '{"es": "This morning se usa para referirse a una parte del día de hoy que ya pasó."}'::jsonb, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0004-000000000001', 'b0000002-0000-0000-0004-000000000003', 4, 'multiple_choice', '{"text": "Choose the correct option: I finished the project ___ 2021."}'::jsonb, '{"text": "in"}'::jsonb, '["at", "on", "ago"]'::jsonb, '{"es": "Con años se usa la preposición in: in 2021."}'::jsonb, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0005-000000000001', 'b0000002-0000-0000-0004-000000000003', 5, 'translation', '{"text": "Ella llegó hace dos semanas."}'::jsonb, '{"text": "She arrived two weeks ago.", "accepted": ["She arrived two weeks ago."]}'::jsonb, NULL, NULL, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0006-000000000001', 'b0000002-0000-0000-0004-000000000003', 6, 'translation', '{"text": "Nosotros trabajamos anoche."}'::jsonb, '{"text": "We worked last night.", "accepted": ["We worked last night."]}'::jsonb, NULL, NULL, '{"vocab:time_expressions"}'),
('b0000003-0003-0004-0007-000000000001', 'b0000002-0000-0000-0004-000000000003', 7, 'word_bank_fill', '{"text": "Last year, we ___ to a new house and ___ all the rooms."}'::jsonb, '{"answers": ["moved", "cleaned"]}'::jsonb, '["move", "cleans"]'::jsonb, '{"es": "Move y clean son verbos regulares: moved y cleaned, usados junto con la expresión last year."}'::jsonb, '{"vocab:time_expressions","grammar:past_simple_regular"}'),
('b0000003-0003-0004-0008-000000000001', 'b0000002-0000-0000-0004-000000000003', 8, 'word_bank_fill', '{"text": "Two days ___, I ___ a letter to my friend."}'::jsonb, '{"answers": ["ago", "mailed"]}'::jsonb, '["last", "mail"]'::jsonb, '{"es": "Ago va después del período de tiempo (two days ago), y mail se conjuga en pasado como mailed."}'::jsonb, '{"vocab:time_expressions","grammar:past_simple_regular"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0004-000000000004', 'b0000001-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 4, 'narrar-en-pasado', '{"es": "Narrar en Pasado", "en": "Narrating in the Past"}'::jsonb, '{"es": "Combina verbos regulares, did y expresiones de tiempo para narrar eventos e historias sencillas en pasado.", "en": "Combine regular verbs, did, and time expressions to narrate simple events and stories in the past."}'::jsonb, 'grammar', 25, 15, '{"intro": "Ya conoces los verbos regulares en pasado, el mecanismo de did para negativos y preguntas, y las expresiones de tiempo. Ahora vas a combinar todo esto para narrar eventos e historias sencillas.", "sections": [{"type": "table", "title": "REPASO: LA ESTRUCTURA COMPLETA", "headers": ["Forma", "Ejemplo"], "rows": [["Afirmativa", "She cleaned the house yesterday."], ["Negativa", "She didn''t clean the house yesterday."], ["Interrogativa", "Did she clean the house yesterday?"], ["Respuesta corta", "Yes, she did. / No, she didn''t."]]}, {"type": "explanation", "title": "CÓMO NARRAR EN PASADO", "text": "Para contar una historia en pasado simple, combina verbos regulares, expresiones de tiempo y las formas negativas o interrogativas con did cuando sea necesario. Usa and para añadir acciones y but para contrastarlas."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "Last weekend, I visited my grandmother.", "es": "El fin de semana pasado, visité a mi abuela."}, {"en": "We cooked dinner together and talked for hours.", "es": "Cocinamos la cena juntos y hablamos por horas."}, {"en": "I didn''t work on Saturday, but I studied on Sunday.", "es": "No trabajé el sábado, pero estudié el domingo."}]}, {"type": "note", "variant": "tip", "text": "Al narrar, recuerda: el verbo lleva -ed solo en afirmativo. En negativo y preguntas, vuelve siempre a su forma base junto con did."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0004-0004-0001-000000000001', 'b0000002-0000-0000-0004-000000000004', 1, 'multiple_choice', '{"text": "Choose the correct sentence:"}'::jsonb, '{"text": "Last night, we watched a movie and ordered pizza."}'::jsonb, '["Last night, we watch a movie and order pizza.", "Last night, we didn''t watched a movie.", "Last night, did we watch a movie."]'::jsonb, '{"es": "En una narración afirmativa, los verbos regulares llevan -ed: watched, ordered."}'::jsonb, '{"grammar:past_simple_regular"}'),
('b0000003-0004-0004-0002-000000000001', 'b0000002-0000-0000-0004-000000000004', 2, 'fill_blank', '{"text": "Last summer, I ___ (travel) to Mexico with my family."}'::jsonb, '{"text": "traveled", "accepted": ["traveled", "travelled"]}'::jsonb, NULL, '{"es": "Travel forma su pasado añadiendo -ed: traveled (también se acepta travelled, ortografía británica)."}'::jsonb, '{"grammar:past_simple_regular"}'),
('b0000003-0004-0004-0003-000000000001', 'b0000002-0000-0000-0004-000000000004', 3, 'fill_blank', '{"text": "We ___ (arrive) at the airport two hours early."}'::jsonb, '{"text": "arrived", "accepted": ["arrived"]}'::jsonb, NULL, '{"es": "Arrive termina en -e, por eso solo se añade -d: arrived."}'::jsonb, '{"grammar:past_simple_regular"}'),
('b0000003-0004-0004-0004-000000000001', 'b0000002-0000-0000-0004-000000000004', 4, 'translation', '{"text": "El año pasado, ella estudió en Londres y aprendió mucho inglés."}'::jsonb, '{"text": "Last year, she studied in London and learned a lot of English.", "accepted": ["Last year, she studied in London and learned a lot of English."]}'::jsonb, NULL, NULL, '{"grammar:past_simple_regular","vocab:time_expressions"}'),
('b0000003-0004-0004-0005-000000000001', 'b0000002-0000-0000-0004-000000000004', 5, 'translation', '{"text": "No visitamos el museo, pero caminamos por el parque."}'::jsonb, '{"text": "We didn''t visit the museum, but we walked in the park.", "accepted": ["We didn''t visit the museum, but we walked in the park."]}'::jsonb, NULL, NULL, '{"grammar:past_simple_negative"}'),
('b0000003-0004-0004-0006-000000000001', 'b0000002-0000-0000-0004-000000000004', 6, 'error_correction', '{"text": "Yesterday, she didn''t called her mother.", "error_word": "called"}'::jsonb, '{"text": "call"}'::jsonb, '["calls", "calling"]'::jsonb, '{"es": "Después de didn''t el verbo vuelve a su forma base: didn''t call, no didn''t called."}'::jsonb, '{"grammar:past_simple_negative"}'),
('b0000003-0004-0004-0007-000000000001', 'b0000002-0000-0000-0004-000000000004', 7, 'error_correction', '{"text": "Did you worked last weekend?", "error_word": "worked"}'::jsonb, '{"text": "work"}'::jsonb, '["works", "working"]'::jsonb, '{"es": "Después de Did el verbo debe estar en forma base: Did you work...?, no Did you worked...?"}'::jsonb, '{"grammar:did_questions"}'),
('b0000003-0004-0004-0008-000000000001', 'b0000002-0000-0000-0004-000000000004', 8, 'multiple_choice', '{"text": "Choose the correct question for this answer: ''Yes, we did.''"}'::jsonb, '{"text": "Did you enjoy the trip?"}'::jsonb, '["Do you enjoy the trip?", "Are you enjoying the trip?", "Were you enjoy the trip?"]'::jsonb, '{"es": "La respuesta corta Yes, we did corresponde a una pregunta con Did en pasado simple."}'::jsonb, '{"grammar:did_questions"}');
